fn concat(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre‐allocate enough space for both input vectors
    let mut c = Vec::with_capacity(a.len() + b.len());
    // Move all elements out of `a` into `c`
    c.extend(a);
    // Move all elements out of `b` into `c`
    c.extend(b);
    c
}

